'use strict'
// Uses a copied profile, never writes the source; output contains no account identifiers/tokens.
const { app, safeStorage, session } = require('electron')
const fs = require('node:fs'), path = require('node:path'), assert = require('node:assert/strict')
const { StableStore } = require('../../desktop/services/store.cjs')
const { SecretStore } = require('../../desktop/services/secrets.cjs')
const { snapshotDatabase, digest } = require('../../desktop/services/upgrade-backup.cjs')
const root = fs.mkdtempSync(path.resolve(__dirname, '../..', '.local/upgrade-account-'))
const original = process.argv.find(a => a.startsWith('--source='))?.slice(9)
if (original && fs.existsSync(path.join(original, 'Local State'))) fs.copyFileSync(path.join(original, 'Local State'), path.join(root, 'Local State'))
app.setPath('userData', root)
app.disableHardwareAcceleration()
app.whenReady().then(async () => {
  const source = process.argv.find(a => a.startsWith('--source='))?.slice(9)
  assert(source, 'source profile required')
  const secretFile = path.join(source, 'secrets.json'), before = digest(secretFile)
  snapshotDatabase(path.join(source, 'stable.db'), path.join(root, 'stable.db'))
  fs.copyFileSync(secretFile, path.join(root, 'secrets.json'))
  const store = new StableStore(root), secrets = new SecretStore(root, safeStorage)
  const token = secrets.get('cloud:device-token'); assert(token, 'Saved cloud token missing')
  const { CloudAccountService } = require('../../desktop/services/cloud-account.cjs')
  const { createCloudFetch } = require('../../desktop/services/cloud-transport.cjs')
  const service = new CloudAccountService({ store, secrets, appVersion: '1.11.0', fetchImpl: createCloudFetch({ session: session.fromPartition('upgrade-account', { cache: false }) }) })
  const result = await service.restore()
  const report = { status: result.status, modelCount: result.models.length, tokenDecrypted: true, tokenRetained: secrets.get('cloud:device-token') === token, originalSecretsUnchanged: digest(secretFile) === before, historyCount: store.db.prepare('SELECT count(*) n FROM messages').get().n }
  fs.writeFileSync(path.join(root, 'result.json'), JSON.stringify(report, null, 2))
  store.close()
  console.log(JSON.stringify({ ...report, evidence: path.join(root, 'result.json') }))
  assert.equal(report.originalSecretsUnchanged, true)
  assert.equal(report.status, 'authenticated')
  app.exit(0)
}).catch(error => { console.error(error.message); app.exit(1) })
